<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignament\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Infrastructure\Driver\Rest\UserRoleAssignamentAllowController;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Infrastructure\Driver\Rest\UserRoleAssignamentListController;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Infrastructure\Driver\Rest\UserRoleAssignamentCreateController;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Infrastructure\Driver\Rest\UserRoleAssignamentRetrieveController;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Infrastructure\Driver\Rest\UserRoleAssignamentUpdateController;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Infrastructure\Driver\Rest\UserRoleAssignamentDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Application\Service\Visibility\UserRoleAssignamentRestrictFilterToVisibility;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Infrastructure\Driven\UserRoleAssignamentReadRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Infrastructure\Driven\UserRoleAssignamentWriteRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\Gateway\UserRoleAssignamentReadGateway;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\Gateway\UserRoleAssignamentWriteGateway;

class UserRoleAssignamentPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[UserRoleAssignamentReadGateway::class] = \DI\autowire(UserRoleAssignamentReadRepositoryAdapter::class);
        $def[UserRoleAssignamentWriteGateway::class] = \DI\autowire(UserRoleAssignamentWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/access/user-role-assignament', [$this, 'setRoutesForUserRoleAssignament']);
        $collector->group('/api/me/acl/access/user-role-assignament', [$this, 'setRoutesForUserRoleAssignamentAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(UserRoleAssignamentRestrictFilterToVisibility::class, TenantAccesible::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("user-role-assignament", "list", "READ");
            $handler->registerResourceAction("user-role-assignament", "create", "WRITE");
            $handler->registerResourceAction("user-role-assignament", "retrieve", "READ");
            $handler->registerResourceAction("user-role-assignament", "update", "WRITE");
            $handler->registerResourceAction("user-role-assignament", "delete", "WRITE");

            $handler->registerResourceAttribute("user-role-assignament", "user", "MANAGE");
            $handler->registerResourceAttribute("user-role-assignament", "relyingParty", "MANAGE");
            $handler->registerResourceAttribute("user-role-assignament", "trustedClient", "MANAGE");
            $handler->registerResourceAttribute("user-role-assignament", "roles", "MANAGE");
            $handler->registerResourceAttribute("user-role-assignament", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForUserRoleAssignamentAcl(RouteCollectorProxy $userRoleAssignamentGroup): void
    {
        $userRoleAssignamentGroup->get('', [UserRoleAssignamentAllowController::class, 'genericAllow']);
        $userRoleAssignamentGroup->get('/{uid}', [UserRoleAssignamentAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForUserRoleAssignament(RouteCollectorProxy $userRoleAssignamentGroup): void
    {
        $userRoleAssignamentGroup->get('', [UserRoleAssignamentListController::class, 'list']);
        $userRoleAssignamentGroup->post('', [UserRoleAssignamentCreateController::class, 'create']);
        $userRoleAssignamentGroup->get('/{uid}', [UserRoleAssignamentRetrieveController::class, 'retrieve']);
        $userRoleAssignamentGroup->put('/{uid}', [UserRoleAssignamentUpdateController::class, 'update']);
        $userRoleAssignamentGroup->delete('/{uid}', [UserRoleAssignamentDeleteController::class, 'delete']);
        $userRoleAssignamentGroup->delete('', [UserRoleAssignamentDeleteController::class, 'deleteAllForQuery']);
        $userRoleAssignamentGroup->get('/~/delete-status/{uid}', [UserRoleAssignamentDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
